1. verus! {
2. 
3. use vstd::bits::lemma_usize_shl_is_mul;
4. use vstd::arithmetic::power2::{pow2, lemma2_to64};
5. use vstd::arithmetic::div_mod::{
6.     lemma_fundamental_div_mod,
7.     lemma_mod_bound,
8.     lemma_mod_multiples_basic,
9. };
10. use vstd::arithmetic::mul::lemma_mul_inequality;
11. 
12. // The physical base address of a frame is its index shifted left by `FRAME_SHIFT`, which equals the
13. // index multiplied by `FRAME_SIZE` and is `FRAME_SIZE`-aligned. The frame-index bound supplied by
14. // `FrameNumber`'s type invariant (`raw <= MAX_ADDRESS / FRAME_SIZE - 1`) keeps the product within
15. // `usize`, so the shift is overflow-free.
16. pub proof fn lemma_frame_address(raw: usize)
17.     requires
18.         0 <= raw as int <= FrameNumber::spec_max(),
19.     ensures
20.         (raw << crate::mem::FRAME_SHIFT) as int == raw as int * (crate::mem::FRAME_SIZE as int),
21.         (raw << crate::mem::FRAME_SHIFT) as int % (crate::mem::FRAME_SIZE as int) == 0,
22. {
23.     let s: int = crate::mem::FRAME_SIZE as int;
24.     let m: int = crate::mem::MAX_ADDRESS as int;
25. 
