     let s: int = crate::mem::FRAME_SIZE as int;
     let m: int = crate::mem::MAX_ADDRESS as int;

     // `pow2(FRAME_SHIFT) == FRAME_SIZE` (i.e. `pow2(12) == 4096`).
     lemma2_to64();
     assert(pow2(crate::mem::FRAME_SHIFT as nat) == crate::mem::FRAME_SIZE);

